-- ts-site-audit 1.0.0 – úlohy auditu webů a limity (MySQL)
CREATE TABLE IF NOT EXISTS ts_audit_jobs (id INT AUTO_INCREMENT PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE, url VARCHAR(500) NOT NULL, url_hash VARCHAR(64) NOT NULL, lang VARCHAR(5) NOT NULL, source VARCHAR(10) NOT NULL, ip_hash VARCHAR(32) NOT NULL DEFAULT '', ref VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(10) NOT NULL, lock_until INT NOT NULL DEFAULT 0, attempts INT NOT NULL DEFAULT 0, data MEDIUMTEXT NOT NULL, error VARCHAR(60) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL, finished_at VARCHAR(19), INDEX ts_audit_jobs_url (url_hash, status), INDEX ts_audit_jobs_created (created_at)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_audit_rate (bucket VARCHAR(120) NOT NULL PRIMARY KEY, window_start INT NOT NULL, count INT NOT NULL DEFAULT 0) DEFAULT CHARSET=utf8mb4;
